export function computeTerazosinBiphasic(doseMg) {
  const d = Math.max(0, Number(doseMg) || 0);
  const stim = (d / (d + 0.18)) * (1.0 / (1.0 + Math.pow(d / 1.45, 2.2)));
  const norm = stim / 0.5466;
  const atpGainPct = Number((norm * 24.5 - (d > 1.3 ? (d - 1.3) * 14 : 0)).toFixed(1));
  const orthostaticPenaltyMmHg = Number((Math.pow(d, 1.35) * 4.8).toFixed(1));
  return {
    doseMg: d,
    pgk1ActivationIndex: Number(Math.max(0, norm).toFixed(3)),
    atpGainPct,
    orthostaticPenaltyMmHg,
    regime:
      d < 0.25
        ? 'Sub-optimal PGK1 occupancy'
        : d <= 0.85
          ? 'Optimal Hormetic PGK1 Window (Peak ~0.59–0.65 mg)'
          : d <= 1.5
            ? 'Descending limb — rising α1-AR hypotensive load'
            : 'Auto-inhibitory high-dose regime (Rule R13 Violation)',
  };
}

export function computeIntranasalInsulinCurve(doseIu) {
  const u = Math.max(0, Number(doseIu) || 0);
  const peakIu = 27.29;
  const raw = 100 - 0.145 * Math.pow(u - peakIu, 2);
  const efficacyPct = Number(Math.max(0, Math.min(100, raw)).toFixed(1));
  const irs1DesensitizationRisk =
    u > 38
      ? 'Elevated (>38 IU receptor internalization)'
      : u >= 20
        ? 'Minimal (Optimal olfactory/trigeminal flux)'
        : 'Low occupancy';
  return {
    doseIu: u,
    analyticalPeakIu: peakIu,
    efficacyPct,
    irs1DesensitizationRisk,
  };
}

export function computeProcollagenBifurcation({
  synthesisMultiplier = 1.85,
  tudcaActive = true,
  pba4Active = true,
  ambroxolActive = true,
  dnl343Active = true,
  s107Active = true,
} = {}) {
  const basePcrit = 1.40;
  const pCrit = Number(
    (
      basePcrit +
      (tudcaActive ? 0.32 : 0) +
      (pba4Active ? 0.34 : 0) +
      (ambroxolActive ? 0.19 : 0) +
      (s107Active ? 0.12 : 0)
    ).toFixed(2)
  );
  const effectiveDemand = Number((Number(synthesisMultiplier) * (dnl343Active ? 1.12 : 1.0)).toFixed(2));
  const margin = Number((pCrit - effectiveDemand).toFixed(2));
  const state =
    margin >= 0.25
      ? 'SAFE_LAMINAR_EXPORT'
      : margin >= 0
        ? 'NEAR_BIFURCATION_THRESHOLD'
        : 'BACKLOG_UPR_APOPTOSIS_WARNING';
  return {
    basePcrit,
    pCrit,
    effectiveDemand,
    margin,
    state,
  };
}

export function evaluateReactorAtHour(hourInput = 144) {
  const h = Math.max(0, Math.min(336, Number(hourInput) || 0));
  const day = Math.min(14, Math.floor(h / 24) + 1);
  const stage =
    h < 144
      ? 'Stage 1A/1B (Days 1–6 · Proliferation, Ribosome Biogenesis & Aggrecan/PAPS Sulfation)'
      : h < 192
        ? 'Stage 2A (Days 7–8 · Cooper Phase-3 Hypertrophic Swelling & Thiol Washout Bridge)'
        : 'Stage 2B (Days 9–14 · CD31hi Emcnhi H-Vessel Invasion & Terminal Osteogenic Conversion)';

  const tauThiol = 19.4;
  let thiolLevel = 1.0;
  if (h <= 138) {
    thiolLevel = 1.0;
  } else if (h <= 150) {
    thiolLevel = 0.5 + 0.5 * Math.exp(-(h - 138) / tauThiol);
  } else {
    const at150 = 0.5 + 0.5 * Math.exp(-12 / tauThiol);
    thiolLevel = at150 * Math.exp(-(h - 150) / tauThiol);
  }

  const tauCapps = 24.0;
  const cappsTarget = h < 144 ? 1.0 : h < 168 ? 0.70 : h < 192 ? 0.35 : 0.0;
  let cappsLevel = cappsTarget;
  if (h >= 192) {
    cappsLevel = 0.35 * Math.exp(-(h - 192) / tauCapps);
  }

  const tauTppu = 36.0;
  let tppuLevel = 0.0;
  if (h >= 180 && h < 192) {
    tppuLevel = 0.35 * (1 - Math.exp(-(h - 180) / tauTppu));
  } else if (h >= 192) {
    const at192 = 0.35 * (1 - Math.exp(-12 / tauTppu));
    tppuLevel = 1.0 - (1.0 - at192) * Math.exp(-(h - 192) / tauTppu);
  }

  return {
    hour: h,
    day,
    stage,
    thiolLevel: Number(thiolLevel.toFixed(3)),
    cappsLevel: Number(cappsLevel.toFixed(3)),
    tppuLevel: Number(tppuLevel.toFixed(3)),
    lithiumActive: h >= 144,
    phytateActive: h < 192,
    sulforaphaneSeleniteActive: h >= 192,
    thiolSafeForStage2B: h < 192 || thiolLevel <= 0.15,
  };
}
